/**
 * @file src/reviewer/question-cloze.ts
 * @summary Renders cloze-deletion flashcard fronts for the reviewer. Parses {{cN::answer}} tokens
 *   in the card text and replaces them with styled blanks (standard mode) or typed inputs (typed mode).
 *
 * @exports
 *   - renderClozeFront — Creates a DOM element rendering a cloze card's text with blanks or revealed answers
 *   - ClozeRenderOptions — Options for cloze rendering (mode, colours, typed-answer state)
 */
import {  } from "obsidian";

import { el, setCssProps } from "../../platform/core/ui";
import { getClozeRenderOccurrences, parseClozeTokens, resolveNestedClozeAnswers } from "../../platform/core/shared-utils";
import { applyInlineMarkdown } from "../../platform/integrations/anki/anki-mapper";
import { hydrateCircleFlagsInElement, processCircleFlagsInMarkdown } from "../../platform/flags/flag-tokens";

/** Options bag for cloze rendering. */
export type ClozeRenderOptions = {
  /** "standard" = normal blanks/reveals; "typed" = text input on front, result on back. */
  mode?: "standard" | "typed";
  /** Custom bg colour for standard-mode revealed cloze (empty = theme accent). */
  clozeBgColor?: string;
  /** Custom text colour for standard-mode revealed cloze (empty = auto-contrast). */
  clozeTextColor?: string;
  /**
    * Map of cloze occurrence key (for example "1#2") → user-typed string.
    * Shared between front and back renders so the back can read what the user typed.
   */
  typedAnswers?: Map<string, string>;
  /** Callback fired whenever a typed input value changes. */
  onTypedInput?: (answerKey: string, clozeIndex: number, value: string) => void;
  /** Callback fired when a typed input receives Enter key. */
  onTypedSubmit?: () => void;
};

function makeTypedAnswerKey(clozeIndex: number, occurrence: number): string {
  return `${clozeIndex}#${occurrence}`;
}

/**
 * Strips inline-markdown markers to produce plain text for comparison.
 * Removes bold, italic, code, and strikethrough formatting.
 */
function stripInlineMarkdown(s: string): string {
  return s
    .replace(/\*\*(.+?)\*\*/g, "$1")
    .replace(/\*(.+?)\*/g, "$1")
    .replace(/_(.+?)_/g, "$1")
    .replace(/~~(.+?)~~/g, "$1")
    .replace(/`(.+?)`/g, "$1")
    .trim();
}

function normalizeTypedClozeForCompare(s: string): string {
  return s
    .trim()
    .normalize("NFKC")
    .toLowerCase()
    // Treat caret exponent notation as equivalent to superscript digits.
    .replace(/\^\s*(?=\d|$)/g, "");
}

function measureClozeTextWidthPx(host: HTMLElement, text: string): number {
  const normalizedText = text.trim();
  if (!normalizedText) return 0;

  const ctx = activeDocument.createElement("canvas").getContext("2d");
  if (!ctx) return normalizedText.length * 8;

  ctx.font = `500 14px ${getComputedStyle(host).fontFamily}`;
  return ctx.measureText(normalizedText).width;
}

function buildTypedClozeInput(
  host: HTMLElement,
  clozeIndex: number,
  occurrence: number,
  answer: string,
  hint: string | null,
  opts?: ClozeRenderOptions,
): HTMLSpanElement {
  const typedAnswers = opts?.typedAnswers ?? new Map<string, string>();
  const plainAns = stripInlineMarkdown(answer);
  const plainHint = stripInlineMarkdown(hint || "");
  const answerKey = makeTypedAnswerKey(clozeIndex, occurrence);

  const wrap = activeDocument.createElement("span");
  wrap.className = "learnkit-cloze-typed-wrap";

  const input = activeDocument.createElement("input");
  input.type = "text";
  input.className = "learnkit-cloze-typed-input";
  input.setAttribute("autocomplete", "off");
  input.setAttribute("autocorrect", "off");
  input.setAttribute("autocapitalize", "off");
  input.setAttribute("spellcheck", "false");
  input.setAttribute("data-cloze-index", String(clozeIndex));
  if (plainHint) input.placeholder = plainHint;

  const textW = Math.max(
    measureClozeTextWidthPx(host, plainAns),
    measureClozeTextWidthPx(host, plainHint),
  );
  setCssProps(input, "width", `${Math.max(60, Math.ceil(textW) + 68)}px`);

  const prev = typedAnswers.get(answerKey);
  if (prev) {
    input.value = prev;
    updateTypedInputState(input, prev, plainAns);
  }

  input.addEventListener("input", () => {
    const v = input.value;
    typedAnswers.set(answerKey, v);
    opts?.onTypedInput?.(answerKey, clozeIndex, v);
    updateTypedInputState(input, v, plainAns);
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      e.stopPropagation();
      opts?.onTypedSubmit?.();
    }
  });

  wrap.appendChild(input);
  return wrap;
}

export function hydrateRenderedMathCloze(
  container: HTMLElement,
  text: string,
  reveal: boolean,
  targetIndex?: number | null,
  opts?: ClozeRenderOptions,
): void {
  if (reveal || (opts?.mode ?? "standard") !== "typed") {
    return;
  }

  const placeholders = Array.from(
    container.querySelectorAll<HTMLElement>(".learnkit-cloze-blank.hidden-cloze"),
  );
  if (!placeholders.length) {
    return;
  }

  const targets = getClozeRenderOccurrences(text, targetIndex).filter(
    (occurrence) => occurrence.isTarget && !occurrence.inMath,
  );


  targets.forEach((occurrence, index) => {
    const placeholder = placeholders[index];
    if (!placeholder) {
      return;
    }

    const host = placeholder.parentElement ?? container;
    const typedWrap = buildTypedClozeInput(
      host,
      occurrence.clozeIndex,
      occurrence.occurrence,
      occurrence.answer,
      occurrence.hint,
      opts,
    );

    placeholder.replaceWith(typedWrap);
  });

    const firstInput = container.querySelector<HTMLInputElement>(".learnkit-cloze-typed-input");
  if (firstInput) {
      const inputToFocus = firstInput;
    window.setTimeout(() => inputToFocus.focus(), 50);
  }
}

export function renderClozeFront(
  text: string,
  reveal: boolean,
  targetIndex?: number | null,
  opts?: ClozeRenderOptions,
): HTMLElement {
  const mode = opts?.mode ?? "standard";
  const typedAnswers = opts?.typedAnswers ?? new Map<string, string>();

  const container = el("div", "");
  container.className = "whitespace-pre-wrap break-words";

  // Wrap cloze content in a <p dir="auto"> so it matches MarkdownRenderer output
  // (and therefore matches spacing/margins between basic vs cloze cards).
  const p = activeDocument.createElement("p");
  p.setAttribute("dir", "auto");
  p.className = "whitespace-pre-wrap break-words";
  container.appendChild(p);

  const clozeOccurrences = new Map<number, number>();

  const measureChPx = (): number => {
    const probe = activeDocument.createElement("span");
    probe.className = "learnkit-cloze-probe";
    probe.textContent = "0000000000";
    p.appendChild(probe);
    const px = probe.getBoundingClientRect().width / 10;
    probe.remove();
    return px || 8;
  };

  const chPx = measureChPx();
  const subtractCh = Math.max(0, Math.round(20 / chPx)); // ~20px in ch units
  const computeBlankWidthPx = (content: string): number => {
    const plainContent = stripInlineMarkdown(content);
    const widthChars = Math.max(4, Math.min(40, plainContent.length || 6));
    const widthAdjusted = Math.max(1, widthChars - subtractCh);
    return Math.max(30, widthAdjusted * chPx);
  };

  const ensureSpaceBeforeBlank = () => {
    const lastNode = p.lastChild;
    const lastText = lastNode?.textContent ?? "";
    if (/\s$/.test(lastText)) return;
    if (lastNode && lastNode.nodeType === Node.TEXT_NODE) {
      lastNode.textContent = lastText + " ";
      return;
    }
    if (lastNode) p.appendChild(activeDocument.createTextNode(" "));
  };

  const applyInlineMarkdownWithFlags = (target: HTMLElement, raw: string) => {
    applyInlineMarkdown(target, processCircleFlagsInMarkdown(raw));
    hydrateCircleFlagsInElement(target);
  };

  /** Append a text segment with inline markdown formatting (bold, italic, etc.) */
  const appendFormattedText = (parent: HTMLElement, text: string) => {
    const span = activeDocument.createElement("span");
    applyInlineMarkdownWithFlags(span, text);
    parent.appendChild(span);
  };

  /** Track first typed input for auto-focus */
  let firstTypedInput: HTMLInputElement | null = null;

  const appendRenderedSegment = (parent: HTMLElement, source: string, activeTargetIndex?: number | null) => {
    const clozeTokens = parseClozeTokens(source).tokens;
    let last = 0;

    for (const token of clozeTokens) {
      if (token.start > last) {
        appendFormattedText(parent, source.slice(last, token.start));
      }

      const idx = token.clozeIndex;
      const answer = token.answer;
      const resolvedAnswer = resolveNestedClozeAnswers(answer);
      const hint = token.hint;
      const plainAns = stripInlineMarkdown(resolvedAnswer);
      const plainHint = stripInlineMarkdown(hint || "");
      const occurrence = (clozeOccurrences.get(idx) ?? 0) + 1;
      clozeOccurrences.set(idx, occurrence);
      const answerKey = makeTypedAnswerKey(idx, occurrence);
      const isTarget = typeof activeTargetIndex === "number" ? idx === activeTargetIndex : true;

      if (!isTarget) {
        appendRenderedSegment(parent, answer, activeTargetIndex);
      } else if (reveal) {
        if (mode === "typed") {
          const typed = (typedAnswers.get(answerKey) ?? "").trim();
          const isCorrect = normalizeTypedClozeForCompare(typed) === normalizeTypedClozeForCompare(plainAns);

          if (isCorrect) {
            const span = activeDocument.createElement("span");
            span.className = "learnkit-cloze-revealed learnkit-cloze-typed-correct";
            applyInlineMarkdownWithFlags(span, resolvedAnswer);
            parent.appendChild(span);
          } else {
            const wrongSpan = activeDocument.createElement("span");
            wrongSpan.className = "learnkit-cloze-revealed learnkit-cloze-typed-wrong";
            wrongSpan.textContent = typed || "\u00A0\u00A0\u00A0";
            parent.appendChild(wrongSpan);
            parent.appendChild(activeDocument.createTextNode(" "));

            const correctSpan = activeDocument.createElement("span");
            correctSpan.className = "learnkit-cloze-revealed learnkit-cloze-typed-correct";
            applyInlineMarkdownWithFlags(correctSpan, resolvedAnswer);
            parent.appendChild(correctSpan);
          }
        } else {
          const answerSpan = activeDocument.createElement("span");
          answerSpan.className = "learnkit-cloze-revealed";
          applyInlineMarkdownWithFlags(answerSpan, resolvedAnswer);

          if (opts?.clozeBgColor) {
            setCssProps(answerSpan, "background-color", opts.clozeBgColor);
          }
          if (opts?.clozeTextColor) {
            setCssProps(answerSpan, "--learnkit-cloze-color", opts.clozeTextColor);
          } else {
            window.setTimeout(() => {
              const bg = getComputedStyle(answerSpan).backgroundColor;
              const rgb = bg.match(/\d+/g)?.map(Number);
              if (rgb && rgb.length >= 3) {
                const [r, g, b] = rgb;
                const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
                setCssProps(answerSpan, "--learnkit-cloze-color", luminance > 0.7 ? "#111111" : "#ffffff");
              }
            }, 0);
          }

          parent.appendChild(answerSpan);
        }
      } else {
        if (mode === "typed") {
          ensureSpaceBeforeBlank();
          const wrap = buildTypedClozeInput(parent, idx, occurrence, resolvedAnswer, hint, opts);
          parent.appendChild(wrap);

          if (!firstTypedInput) firstTypedInput = wrap.querySelector<HTMLInputElement>("input");
        } else if (hint) {
          const hintSpan = activeDocument.createElement("span");
          hintSpan.className = "learnkit-cloze-hint";
          applyInlineMarkdownWithFlags(hintSpan, hint);
          setCssProps(hintSpan, "width", `${computeBlankWidthPx(plainAns || plainHint)}px`);
          parent.appendChild(hintSpan);
        } else {
          ensureSpaceBeforeBlank();

          const blank = activeDocument.createElement("span");
          blank.className = "learnkit-cloze-blank hidden-cloze";
          blank.textContent = "";
          setCssProps(blank, "--learnkit-cloze-width", `${computeBlankWidthPx(plainAns)}px`);

          parent.appendChild(blank);
        }
      }

      last = token.end;
    }

    if (last < source.length) {
      appendFormattedText(parent, source.slice(last));
    }
  };

  appendRenderedSegment(p, text, targetIndex);

  // Auto-focus the first typed input when in typed mode
  if (firstTypedInput) {
    const inputToFocus: HTMLInputElement = firstTypedInput;
    window.setTimeout(() => inputToFocus.focus(), 50);
  }

  return container;
}

/**
 * Updates the visual state of a typed cloze input based on current value vs expected answer.
 * - Empty: neutral (no state class)
 * - Partial match from start: yellow ("partial")
 * - Full match: green ("correct")
 * - Mismatch: red ("wrong")
 */
function updateTypedInputState(input: HTMLInputElement, typed: string, expected: string) {
  input.classList.remove(
    "learnkit-cloze-typed--partial", "learnkit-cloze-typed--partial",
    "learnkit-cloze-typed--correct", "learnkit-cloze-typed--correct",
    "learnkit-cloze-typed--wrong", "learnkit-cloze-typed--wrong",
  );

  if (!typed) return; // empty → neutral

  const tLower = normalizeTypedClozeForCompare(typed);
  const eLower = normalizeTypedClozeForCompare(expected);

  if (tLower === eLower) {
    input.classList.add("learnkit-cloze-typed--correct", "learnkit-cloze-typed--correct");
  } else if (eLower.startsWith(tLower)) {
    input.classList.add("learnkit-cloze-typed--partial", "learnkit-cloze-typed--partial");
  } else {
    input.classList.add("learnkit-cloze-typed--wrong", "learnkit-cloze-typed--wrong");
  }
}
