/**
 * @file src/widget/widget-buttons.ts
 * @summary Standalone UI factory functions for the Sprout sidebar widget. Provides reusable button builders (icon-only and text variants), styling helpers for action buttons and hover states, and the "More" dropdown menu attachment logic.
 *
 * @exports
 *  - applyWidgetHoverDarken       — adds hover colour-darken transitions to an element
 *  - makeIconButton               — creates an icon-only button with a tooltip
 *  - makeTextButton               — creates a text button with an optional keyboard-hint badge
 *  - applyWidgetActionButtonStyles — applies the standard action-button class and styles
 *  - attachWidgetMoreMenu         — creates and attaches the "More" dropdown menu to a container
 */

import { setIcon } from "obsidian";
import { log } from "../../../platform/core/logger";
import { placePopover } from "../../../platform/core/ui";
import { t } from "../../../platform/translations/translator";

/* ------------------------------------------------------------------ */
/*  Hover colour helper                                                */
/* ------------------------------------------------------------------ */

/**
 * Applies CSS variable-based hover/focus darkening to a button.
 * Sets background and border colours on mouseenter/focus and reverts
 * on mouseleave/blur.
 */
export function applyWidgetHoverDarken(btn: HTMLButtonElement) {
  btn.classList.add("learnkit-widget-hover-darken", "learnkit-widget-hover-darken");
}

/* ------------------------------------------------------------------ */
/*  Icon button factory                                                */
/* ------------------------------------------------------------------ */

/**
 * Creates a square icon button with a tooltip label.
 *
 * @param opts.icon   – Lucide icon name (passed to Obsidian `setIcon`)
 * @param opts.label  – Tooltip text (via `aria-label`)
 * @param opts.title  – Optional tooltip override
 * @param opts.className – CSS classes
 * @param opts.onClick   – Click handler
 */
export function makeIconButton(opts: {
  icon: string;
  label: string;
  title?: string;
  className: string;
  onClick: () => void;
}): HTMLButtonElement {
  const btn = activeDocument.createElement("button");
  btn.type = "button";
  btn.className = opts.className;
  btn.setAttribute("aria-label", opts.title || opts.label);
  btn.setAttribute("data-tooltip-position", "top");
  setIcon(btn, opts.icon);
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    opts.onClick();
  });
  applyWidgetHoverDarken(btn);
  return btn;
}

/* ------------------------------------------------------------------ */
/*  Text button factory                                                */
/* ------------------------------------------------------------------ */

/**
 * Creates a text button with an optional keyboard-shortcut badge.
 *
 * @param opts.label     – Button label text
 * @param opts.title     – Optional tooltip override
 * @param opts.className – CSS classes
 * @param opts.onClick   – Click handler
 * @param opts.kbd       – Optional keyboard shortcut string shown as a `<kbd>` badge
 */
export function makeTextButton(opts: {
  label: string;
  subtitle?: string;
  title?: string;
  className: string;
  onClick: () => void;
  kbd?: string;
}): HTMLButtonElement {
  const btn = activeDocument.createElement("button");
  btn.type = "button";
  btn.className = opts.className;
  btn.setAttribute("aria-label", opts.title || opts.label);
  btn.setAttribute("data-tooltip-position", "top");

  if (opts.subtitle) {
    btn.classList.add("sprout-widget-btn-with-subtitle");
    const labelWrap = activeDocument.createElement("span");
    labelWrap.className = "sprout-widget-btn-label-wrap";

    const labelLine = activeDocument.createElement("span");
    labelLine.className = "learnkit-grade-btn-label";
    labelLine.textContent = opts.label;

    const subtitleLine = activeDocument.createElement("span");
    subtitleLine.className = "sprout-widget-btn-subtitle";
    subtitleLine.textContent = opts.subtitle;

    labelWrap.appendChild(labelLine);
    labelWrap.appendChild(subtitleLine);
    btn.appendChild(labelWrap);
  } else {
    const content = activeDocument.createElement("span");
    content.textContent = opts.label;
    btn.appendChild(content);
  }

  if (opts.kbd) {
    const kbd = activeDocument.createElement("kbd");
    kbd.className = "kbd sprout-widget-kbd";
    kbd.textContent = opts.kbd;
    btn.appendChild(kbd);
  }

  btn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    opts.onClick();
  });
  applyWidgetHoverDarken(btn);
  return btn;
}

/* ------------------------------------------------------------------ */
/*  Action button styling                                              */
/* ------------------------------------------------------------------ */

/** Adds the shared `sprout-widget-action-btn` class to a button. */
export function applyWidgetActionButtonStyles(btn: HTMLButtonElement) {
  btn.classList.add("learnkit-widget-action-btn", "learnkit-widget-action-btn");
}

/* ------------------------------------------------------------------ */
/*  "More" dropdown menu                                               */
/* ------------------------------------------------------------------ */

/**
 * Attaches a dropdown menu to a trigger button with options for
 * Open, Bury, Suspend, and Undo.  The menu is positioned relative
 * to the trigger and auto-closes on outside click or Escape.
 *
 * @returns `{ toggle, close, isOpen }` control handles
 */
export function attachWidgetMoreMenu(opts: {
  trigger: HTMLButtonElement;
  locale?: unknown;
  canUndo: boolean;
  onUndo: () => void;
  canBurySuspend: boolean;
  onBury: () => void;
  onSuspend: () => void;
  openStudy?: () => void;
  openNote?: () => void;
}): { toggle: () => void; close: () => void; isOpen: () => boolean } {
  const tx = (token: string, fallback: string) => t(opts.locale, token, fallback);
  const id = `learnkit-widget-menu-${Math.random().toString(36).slice(2, 8)}`;
  const trigger = opts.trigger;
  trigger.id = `${id}-trigger`;
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.setAttribute("aria-controls", `${id}-menu`);
  trigger.setAttribute("aria-expanded", "false");

  const popover = activeDocument.createElement("div");
  popover.id = `${id}-popover`;
  popover.className = "learnkit";
  popover.setAttribute("aria-hidden", "true");
  popover.classList.add("learnkit-popover-overlay", "learnkit-popover-overlay");

  const panel = activeDocument.createElement("div");
  panel.className = "learnkit rounded-md border border-border bg-popover text-popover-foreground shadow-lg p-1 pointer-events-auto";
  popover.appendChild(panel);

  const menu = activeDocument.createElement("div");
  menu.className = "learnkit flex flex-col";
  menu.setAttribute("role", "menu");
  menu.id = `${id}-menu`;
  panel.appendChild(menu);

  const addItem = (label: string, hotkey: string | null, onClick: () => void, disabled = false, ariaLabel?: string) => {
    const item = activeDocument.createElement("div");
    item.className =
      "group flex items-center justify-between gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer select-none outline-none hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground";
    item.setAttribute("role", "menuitem");
    item.tabIndex = disabled ? -1 : 0;
    item.setAttribute("aria-label", ariaLabel ?? label);
    if (disabled) {
      item.classList.add("learnkit-menu-item--disabled", "learnkit-menu-item--disabled");
      item.setAttribute("aria-disabled", "true");
    }

    const labelSpan = activeDocument.createElement("span");
    labelSpan.className = "";
    labelSpan.textContent = label;
    item.appendChild(labelSpan);

    if (hotkey) {
      const key = activeDocument.createElement("kbd");
      key.className = "kbd ml-auto text-xs text-muted-foreground tracking-widest";
      key.textContent = hotkey;
      item.appendChild(key);
    }

    const activate = () => {
      if (disabled) return;
      onClick();
      close();
    };

    item.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      activate();
    });

    item.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        e.stopPropagation();
        activate();
      }
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        close();
        trigger.focus();
      }
    });

    menu.appendChild(item);
  };

  if (typeof opts.openNote === "function") {
    addItem(
      tx("ui.widget.moreMenu.openInNote", "Open in Note"),
      "O",
      opts.openNote,
      false,
      tx("ui.widget.moreMenu.aria.openInNote", "Open flashcard in parent note"),
    );
  }
  addItem(
    tx("ui.widget.moreMenu.bury", "Bury"),
    "B",
    opts.onBury,
    !opts.canBurySuspend,
    tx("ui.widget.moreMenu.aria.bury", "Bury flashcard"),
  );
  addItem(
    tx("ui.widget.moreMenu.suspend", "Suspend"),
    "S",
    opts.onSuspend,
    !opts.canBurySuspend,
    tx("ui.widget.moreMenu.aria.suspend", "Suspend flashcard"),
  );
  if (typeof opts.openStudy === "function") {
    addItem(
      tx("ui.widget.moreMenu.transferToStudy", "Transfer to Study"),
      "T",
      opts.openStudy,
      false,
      tx("ui.widget.moreMenu.aria.transferToStudy", "Transfer to Study"),
    );
  }
  addItem(
    tx("ui.widget.moreMenu.undoLastGrade", "Undo last grade"),
    "U",
    opts.onUndo,
    !opts.canUndo,
    tx("ui.widget.moreMenu.aria.undoLastGrade", "Undo previous review and grading"),
  );

  let cleanup: (() => void) | null = null;

  const place = () => placePopover({ trigger, panel, popoverEl: popover, align: "right" });

  const close = () => {
    trigger.setAttribute("aria-expanded", "false");
    popover.setAttribute("aria-hidden", "true");
    popover.classList.remove("is-open");

    try {
      cleanup?.();
    } catch (e) { log.swallow("popover cleanup", e); }
    cleanup = null;

    try {
      popover.remove();
    } catch (e) { log.swallow("remove popover", e); }
  };

  const open = () => {
    trigger.setAttribute("aria-expanded", "true");
    popover.setAttribute("aria-hidden", "false");
    popover.classList.add("is-open");

    activeDocument.body.appendChild(popover);
    window.requestAnimationFrame(() => place());

    const onResizeOrScroll = () => place();
    const onDocPointerDown = (ev: PointerEvent) => {
      const t = ev.target as Node | null;
      if (!t) return;
      if (trigger.contains(t) || popover.contains(t)) return;
      close();
    };
    const onDocKeydown = (ev: KeyboardEvent) => {
      if (ev.key !== "Escape") return;
      ev.preventDefault();
      ev.stopPropagation();
      close();
      trigger.focus();
    };

    window.addEventListener("resize", onResizeOrScroll, true);
    window.addEventListener("scroll", onResizeOrScroll, true);

    const tid = window.setTimeout(() => {
      activeDocument.addEventListener("pointerdown", onDocPointerDown, true);
      activeDocument.addEventListener("keydown", onDocKeydown, true);
    }, 0);

    cleanup = () => {
      window.clearTimeout(tid);
      window.removeEventListener("resize", onResizeOrScroll, true);
      window.removeEventListener("scroll", onResizeOrScroll, true);
      activeDocument.removeEventListener("pointerdown", onDocPointerDown, true);
      activeDocument.removeEventListener("keydown", onDocKeydown, true);
    };
  };

  const toggle = () => {
    const isOpen = trigger.getAttribute("aria-expanded") === "true";
    if (isOpen) close();
    else open();
  };

  trigger.addEventListener("pointerdown", (ev: PointerEvent) => {
    if (ev.button !== 0) return;
    ev.preventDefault();
    ev.stopPropagation();
    toggle();
  });

  return { toggle, close, isOpen: () => trigger.getAttribute("aria-expanded") === "true" };
}
